cards=[]
cards.append(compact('dian_xiwei','典希微','典希微是一位兴趣广泛而自信的年轻女子，任空手道学校教练，也懂梅花剑、古典文字和多国语言文化。她在蓄水湖边遇见两个形迹诡异的人，虽受惊仍能观察、询问，而不是跟着男伴只顾逃跑；此后与张泰丰相识相恋。她喜欢探险，甚至愿意捐出大笔费用换取参加机会，常把可能出现的意外理解成刺激，也会以探险高贵所以不可能行骗的说法为自己的选择辩护。赴巴拿马途中，队伍遭武装匪徒袭击，她迅速叫人伏下、取枪应对，事后仔细查看尸体。未知力量把众人摄上空中时，她仍尽力用颜料留下十二个箭头，进入陌生空间后又让大家聚在一起、不要乱碰，并坚持向机器人模样的存在问清目的。她愿意留下继续接触，遭拒后还自信地说封存的记忆总能打开，实际回到人间却完全不记得那段经历。努力大师后来在她不知情时使她重演片段，结束后她仍未保有完整回忆。她的终局是完成探险、继续有感情和好奇心的生活，不是获得外星技术或精神免疫；勇气和敏锐可以让她留下线索，却不保证每次判断都安全或正确。','完成四个月探险返回，未知经历的记忆仍被封存；曾在催眠中重演片段但未自主恢复','重要配角','主动经历陌生世界，不愿因别人的担忧放弃自己想做的事情','主动结交、追问和研究，愿为有兴趣的活动投入金钱与时间','危险真实出现时能迅速观察、保护同伴并留下线索，但事前也会轻视风险','勇敢不等于无惧或无误，身体和记忆仍受外力影响',[ab('武术与临场应变','空手道教练、会梅花剑，面对武装袭击能快速伏下和组织同伴','探险队缺乏实战经验；不能据教练身份保证抗自动武器'),ab('探险观察与留迹','受束缚上升时仍喷出箭头，查看尸体并在陌生空间保持团队秩序','需随身工具和短暂动作空间，无自发飞行或空间能力'),ab('广泛学识','对古典文学、甲骨文及瑜伽等有兴趣和知识','兴趣不等于各领域顶级专家；未知解释仍可误判')],[ev('129',1376,1438,'教练与遭遇两鬼时观察'),ev('130',831,879,'武文兴趣、资助探险及风险态度'),ev('130',2442,2505,'应袭、查尸、箭头与接触未知者'),ev('130',2532,2552,'记忆封存及催眠后的不知情')],profile='investigator',extra={'uncertainties':['她对探险不会骗局的信念是人物盲点，不是事实。','催眠重演让旁观者知道片段，不等于她永久解开外星封存。']}))
cards.append(compact('feinandu','费南度','费南度是巴拿马警方地位很高的警官，身材庞大，喜欢酒和交朋友，初见时容易被人用外形低估。他负责的一宗银行抢案里，三个本来要伤人的匪徒相继把枪转向自身，案件表面已经结束，他却不肯只以恶人自食其果结案。他组织小组处理监控影像，反复核对极短时间里的手臂、表情和左手动作，注意到匪徒可能正想阻止自己右手，因本地无人认真讨论而把疑问带到国际会议，再经张泰丰找到卫斯理。他愿承认自己不知道，也会因听到支持自己推测的话而过度兴奋，但核心动力是解释可核现象。后来探险队遭袭失踪，他运用警务位置调集搜索和人员，把消息及时传给卫家，同时保留让专家进一步调查的空间。他与红绫由尴尬误会变成以好酒相交，显示其身份之外随和的一面。终局他仍是有管辖和资源边界的警官，调查让他更接近异星信号逆转的解释，却没有因此掌握那套力量。卡片应保留他不怕被笑多事的执拗和对微小证据的认真，而不是把体重、警衔或好酒量转换成超人力量。','继续负责巴拿马警务，探险队平安回返；等待卫等转告异常机制的后续解释','主角','把已经发生却无法解释的事实查清，不能因案件表面结束就忽略它','以录像、证词和现场结果组织分析，喜欢在朋友间交流设想','发现重要细节被草率否定时坚持追问，但不会假装已有答案','解释必须与影像事实相符，怪异不构成放弃调查的理由',[ab('影像与案件分析','组织慢动作处理、核验动作顺序，提出不由自主开枪的疑点','加工为观察用慢放并非制造原事件；判断仍需外部证据'),ab('警务协调','以高级警官身份安排资料、人员、搜索及联络','权力属于具体警务环境，不能自动调动其他国家或全部军队')],[ev('130',114,210,'个性、警务地位和与红绫交友'),ev('130',270,343,'影像核验与表情提问'),ev('130',428,475,'留意左手动作'),ev('130',557,569,'无人讨论仍求外界帮助'),ev('130',2053,2095,'探险队信息及时联络'),ev('130',2361,2368,'派员合作并等待解释')],profile='expert'))
cards.append(compact('nuli_master','努力大师','努力大师由白素经非人协会寻找而来，是一位外貌普通到难以引起注意的人。他讲话不多、眼神不显锐利，并没有通常想象中以逼人目光施术的姿态，真正擅长的是让人在不知不觉间进入催眠。他也有很深的瑜伽造诣，可以用动作吸引有兴趣者的注意，再把声音、模仿和暗示结合起来，使被封存的经历以身体动作与语言重演。典希微被告知来观看瑜伽示范，不知道自己将被催眠；大师模拟枪声、雷雨和现场过程，让她呈现探险队遇袭、上升、进入未知空间以及与机器人交流的片段。这个过程给旁观者留下重要信息，也暴露了当事人并未事先知情的边界，不能被改写为无条件同意。施术对他代价很大：他原先预计较好情况下只能维持三分钟，随后至少三年失去这项能力，却在此次坚持了近二十分钟。他最后满头大汗、步履不稳，明确说再也不能，离开前解除典希微的状态。终局不是可以每天重复读取所有人的大师，而是能力已耗尽、恢复时程可能更久的协助者；保留瑜伽、口技与经验，不自动清零恢复代价。','超额维持催眠近二十分钟后耗竭离去；至少三年失去该催眠能力，实际恢复未展示','主角','以难得本领揭开封存记忆中的事实，但在极限到来时明确停止','少言、低调，用瑜伽和逼真声音建立施术条件','需要关键信息时可承担超额代价，耗竭后拒绝立即再来','本领有恢复成本，旁人迫切想知道不构成无限续施的理由',[ab('瑜伽与口技','精深动作和逼真枪雷雨声可作为注意引导及场景模拟','不等于真实制造雷雨或枪弹'),ab('封存记忆的催眠重演（终局不可用）','曾在典希微不察觉时使她以动作和话语重演封存片段','本次后至少三年失能，恢复未落实；不是永久解封或读取任何人',kind='历史能力')],[ev('130',2383,2412,'经协会寻找、普通外貌与特殊催眠门派'),ev('130',2420,2448,'未告知的瑜伽示范及声音重演'),ev('130',2540,2555,'耗竭、解除、至少三年失能')],profile='expert',extra={'version':{'basis':'采用最后已耗竭状态，不把历史成功当终局可重复招式','canonical_endpoint':'施术近二十分钟后离去，至少三年失去催眠能力','deployment':'保留瑜伽、口技和施术知识，催眠需明确经过恢复并重新核实后才可启用；默认初次参演仍不可用。'},'uncertainties':['至少三年是原预计三分钟施术后的代价，超时后实际是否更长未知。','由协会牵线不等于其会员身份已确认。']}))
cards.append(compact('thunder_arbiter','雷电中的秩序维护者','这个机器人模样的存在只通过典希微被封存经历的重演向读者显现。它可能是外星人的机器，也可能本来就是有机器人外形的外星生命，文本没有把两种身份判定清楚。它自述来到地球维持高级生物的秩序，能够接收恶行发生前的脑部信号并令其逆转，使原本要伤害他人的动作转而伤害行为者自己。银行匪徒的反常自射和山中匪徒相互开枪，与这种机制相符，但不等于它能无条件判定一切道德或翻转所有自然伤害。逆转需要强力雷电配合，它为什么不在每场雷雨中执行、是否能存储信号，故事没有答案。它或所依托设施把探险队带入空中未知空间，与典希微交谈，却不允许他们长期留下，回返前封存了这段记忆，使他们以为自己一直按原计划行进。民间果报之神的形象被拿来与它联系，那是理解现象的传统名称，不是授予它宇宙因果主宰权。终局它仍未公开向卫等出现，部署须保留作用条件、身份不明及设备依赖，不能因为主持者认定某人邪恶就让它跨世界无限追罚。','接触探险队后封存其相关记忆并送回；去向、常驻范围及后续出手未明',['主角','阶段性对立者'],'按自身规则维护地球高级生物的秩序，并限制接触者对其设施的了解','通过信号识别与有限交流行动，不以人类法律或情绪直接代替机制','在适合的雷电条件下逆转特定伤害意图；对要求留下的来者拒绝并封存记忆','维护秩序是其宣称目的，实际适用范围与价值判断仍需证据',[ab('恶行脑信号逆转','接收行动前的脑部信号并使动作方向逆转，导致恶徒自伤或互射','必须强力雷电配合；只见具体人类袭击，不是绝对因果反伤',kind='精神技术'),ab('空间接触与记忆封存','依不明设施将探险队摄入空中空间，交流后送回并封存该段记忆','位置、能源和范围未知；高代价催眠仍能重演片段，不是绝对不可窥破',kind='设施技术')],[ev('130',281,344,'银行自射与非本意迹象'),ev('130',2271,2295,'山中九匪互射由弹道证实'),ev('130',2478,2519,'上升、机器形态、信号逆转与雷电条件'),ev('130',2530,2555,'拒留、封存与催眠仍能重演')],profile='expert',aliases=['果报之神（人物联系）'],extra={'baseline':{'destruction':'间接令已有枪械伤害转向施害者，未展示凭空造出同等火力。','durability':'机器人状本体或设备的材质耐久未知，不能按神名赋予不灭。','speed':'有把人带往空中空间的设施效应，不等于肉身无限移动。','energy':'精神信号逆转借强雷电条件，未证可自行生成同等雷电。','mind':'能读取特定行为信号、封存记忆，未证全知全能或完全抗催眠。','stamina':'环境、装置及能源范围不明，不能无条件持续对全地球运行。'},'uncertainties':['机器与外星本体身份未决；不可强并别书同称神的存在。','储存逆转信号待雷雨再发作只是卫的设想。']}))
rate(cards[-1],[0,6,5,5,6,4],neg=(2,4,1),tier='凶',reason='局部脑信号干预、载人转移与封存依赖设施和强雷电，没有概念因果权柄',mastery='基本掌握')
cards.append(compact('thunder_bank_robbers','银行劫案的三名面具匪徒','这三名没有公布姓名的匪徒组成一支熟练的银行抢劫小组，戴节庆面具遮住身份，携一柄手提机枪和两柄短枪进入小银行。他们以先开枪、再喝令的方式制造惊恐，随后分工控制警卫、经理和全场，没有因现场有孩子或妇女而收敛。持机枪者见警卫想反抗，准备立即射杀，却在扣枪时把枪口转向自己的胸口而死；另一人见经理挣脱，举枪欲射，也将枪转向自己头部，左手还试图干预右手；最后一人惊恐失控，喊着不要仍然开枪自射。全过程不到半分钟，录像保留了与自愿求死不符的惊讶和挣扎，使他们成为调查异常机制的关键。至少持机枪者被警方列为重大通缉犯，牵涉多宗抢劫谋杀；这一履历不能无差别分配给三人每一个。后续说明其行为受到脑信号逆转，不代表他们有自伤复活术或忽然悔改。本卡以匿名犯罪小组作有限群体条目，参演恢复案发前的三名常人及有限枪械，群体内部只保留已见分工，不编造姓名、完整家世或超出常规武器的火力。','三人均在银行现场受信号逆转而自射死亡；无生还或复活证明','反派','以暴力快速取得钱财，反抗出现时用杀人维持控制','按分工进入、威吓、控制柜台和警卫','行动被抵抗或同伴死亡时更容易失控开枪，未知逆转使计划反噬','他人生命被视为障碍，其临死恐惧不等于已经悔悟',[ab('协同持械抢劫','三人以一机枪两手枪分工控制小范围现场','弹药、视线与人类身体受限；脑信号被逆转时武器可伤及本人')],[ev('130',29,55,'人数、枪械、分工与杀人意图'),ev('130',281,370,'首人自射、警方既往记录'),ev('130',403,445,'第二人失控自射和左手动作'),ev('130',525,545,'第三人死亡及全组结果')],profile='investigator',extra={'version':{'basis':'已死匿名群体显式恢复案发前有限人员参演','canonical_endpoint':'三人均在现场自射死亡','deployment':'恢复案发前的三名常人与所列有限枪械；受逆转是其败亡机制，不作为自己的能力。'},'adaptations':[{'change':'作为有共同目标和明确分工的三人组恢复参演。','reason':'匿名反派有实际行动而无足够身份资料逐个编造。','power_impact':'不增加人数、枪械种类或复活能力。'}]}))
cards.append(compact('thunder_mountain_bandits','袭击巴拿马探险队的九名匪徒','这九名没有留下姓名的武装匪徒在探险队途经河道时占据平台，趁大雷雨突然出现、视线恶化而发动袭击。他们事先在有利位置等待，队伍接近平台才一同起身持械呼喝，随后立即响起枪声。探险者虽然携有武器，却缺乏实战经验，只能慌乱伏下与扫射，本来并不具备轻易歼灭伏击者的条件。雷雨过后，九名匪徒都已中枪倒地，警方后来通过致命子弹与枪械的弹道对照确认，他们的死亡来自彼此射击。这个事实与银行匪徒突然自射的事件被联系起来，最终由典希微的催眠重演提供了脑部信号逆转的解释。故事没有逐一说明这些人的姓名、排行、动机差别或更大的组织，不能把当地所有犯罪势力都算入此组。群体卡只保留伏击、地形利用和常规枪械威胁，也明确其战术优势仍会被未知精神干预破坏。他们并非主动集体求死，互射更不意味着获得了把伤害返还敌人的能力。参演时恢复最后可行动的九人小组，人数和枪弹保持有限，不因出场即败亡就补造足以抵抗外星控制的意志或护符。','九人于袭击现场互射死亡，弹道检查证实；无幸存者或后续独立人格信息','反派','利用隐蔽和火力袭击经过者，具体利益分配与组织背景未知','占据有利地形等待，接近后突然威吓与开火','遭反击时以原有武器应对，却无法识别或抵抗导致互射的精神作用','保持有限犯罪小组的现场逻辑，不代其编造统一宏大信条',[ab('地形伏击与枪械','九人占平台对河中经过的探险队发起武装袭击','天气影响视线，常人易伤；逆转信号可破坏瞄准和敌我判断')],[ev('130',2264,2277,'平台、雷雨、伏击与全组死亡'),ev('130',2282,2295,'警方弹道确认互射'),ev('130',2461,2469,'典希微事后查看时只有初步怀疑'),ev('130',2504,2519,'信号逆转解释与环境条件')],profile='investigator',extra={'version':{'basis':'已死匿名九人组显式恢复最后可行动状态参演','canonical_endpoint':'九名袭击者全数死亡','deployment':'恢复袭击前九名常人及有限常规枪械；不带造成其死亡的异星技术。'},'adaptations':[{'change':'以明确人数和共同现场目标构成群体卡，恢复案发前状态。','reason':'个体身份不足以拆成九个有差异的角色。','power_impact':'没有额外成员、组织火力或精神抗性。'}]}))
